    "id": "builtin-fda-snapshot-nuzolvence",
    "builtin": true,
    "title": "FDA Drug Trials Snapshot · NUZOLVENCE",
    "category": "Pharmacy",
    "folderId": "folder-pharmacy-public-health",
    "materialType": "fda-drug-trials-snapshot",
    "source": "U.S. Food and Drug Administration · NUZOLVENCE Drug Trials Snapshot",
